param([string]$Output = (Join-Path $PSScriptRoot 'OpenAoIPWdm.inf'))
$ErrorActionPreference = 'Stop'
$taskLines = [Collections.Generic.List[string]]::new()
$taskHeader = @'
; Generated by generate-inf.ps1. Stereo endpoint IDs must match endpoint_name() in the driver.
[Version]
Signature="$WINDOWS NT$"
Class=MEDIA
ClassGuid={4d36e96c-e325-11ce-bfc1-08002be10318}
Provider=%Provider%
DriverVer=11/25/2026,0.5.0.0
CatalogFile=OpenAoIPWdm.cat
PnpLockdown=1
[Manufacturer]
%Provider%=OpenAoIP,NTamd64.10.0...26100
[OpenAoIP.NTamd64.10.0...26100]
%Device%=Device,Root\OpenAoIPWdm
[DestinationDirs]
DriverCopy=13
[SourceDisksNames]
1=%Disk%,,,
[SourceDisksFiles]
OpenAoIPWdm.sys=1
[DriverCopy]
OpenAoIPWdm.sys
[Device.NT]
Include=ks.inf,wdmaudio.inf
Needs=KS.Registration,WDMAUDIO.Registration
CopyFiles=DriverCopy
AddReg=DriverRegistration,EndpointNames
[DriverRegistration]
HKR,,AssociatedFilters,,"wdmaud"
HKR,,Driver,,OpenAoIPWdm.sys
HKR,Drivers,SubClasses,,"wave,mixer"
HKR,Drivers\wave\wdmaud.drv,Driver,,wdmaud.drv
HKR,Drivers\wave\wdmaud.drv,Description,,%Device%
HKR,Drivers\mixer\wdmaud.drv,Driver,,wdmaud.drv
HKR,Drivers\mixer\wdmaud.drv,Description,,%Device%
[Device.NT.Services]
AddService=OpenAoIPWdm,0x00000002,Service
[Service]
DisplayName=%Device%
ServiceType=1
StartType=3
ErrorControl=1
ServiceBinary=%13%\OpenAoIPWdm.sys
[Device.NT.HW]
AddReg=Hardware
[Hardware]
HKR,,DeviceType,0x00010001,0x0000001d
HKR,,Security,,"D:P(A;;GA;;;SY)(A;;GA;;;BA)(A;;GRGWGX;;;AU)"
[EndpointNames]
'@
$taskLines.AddRange([string[]]($taskHeader -split '\r?\n'))
for ($taskPair=0; $taskPair -lt 16; $taskPair++) {
    $taskLabel = '{0:00}/{1:00}' -f ($taskPair*2+1),($taskPair*2+2)
    foreach ($taskDirection in @('Render','Capture')) {
        $taskBase = if ($taskDirection -eq 'Render') { 0x9f65b000L } else { 0x9f65c000L }
        $taskGuid = '{{{0:x8}-38dc-4427-a39e-c7106d981865}}' -f ($taskBase+$taskPair)
        $taskName = if ($taskDirection -eq 'Render') { "OpenAoIP Senden $taskLabel" } else { "OpenAoIP Empfang $taskLabel" }
        $taskLines.Add(('HKR,"MediaCategories\{0}",Name,,"{1}"' -f $taskGuid,$taskName))
    }
}
$taskLines.Add('[Device.NT.Interfaces]')
for ($taskPair=0; $taskPair -lt 16; $taskPair++) {
    foreach ($taskDirection in @('Render','Capture')) {
        $taskId = '{0}{1:00}' -f $taskDirection,$taskPair
        foreach ($taskCategory in @('Audio','Realtime',$taskDirection)) { $taskLines.Add(('AddInterface=%{0}%,Wave{1},Wave{1}' -f $taskCategory,$taskId)) }
        foreach ($taskCategory in @('Audio','Topology')) { $taskLines.Add(('AddInterface=%{0}%,Topology{1},Topology{1}' -f $taskCategory,$taskId)) }
    }
}
# WAVEFORMATEXTENSIBLE: stereo, PCM16, 48 kHz, stereo speaker mask.
$taskFormat = 'fe,ff,02,00,80,bb,00,00,00,ee,02,00,04,00,10,00,16,00,10,00,03,00,00,00,01,00,00,00,00,00,10,00,80,00,00,aa,00,38,9b,71'
for ($taskPair=0; $taskPair -lt 16; $taskPair++) {
    $taskLabel = '{0:00}/{1:00}' -f ($taskPair*2+1),($taskPair*2+2)
    foreach ($taskDirection in @('Render','Capture')) {
        $taskId = '{0}{1:00}' -f $taskDirection,$taskPair
        $taskName = if ($taskDirection -eq 'Render') { "OpenAoIP Senden $taskLabel" } else { "OpenAoIP Empfang $taskLabel" }
        $taskFactor = if ($taskDirection -eq 'Render') { 1 } else { 4 } # Speakers / Microphone.
        foreach ($taskKind in @('Wave','Topology')) {
            $taskSection = "$taskKind$taskId"
            $taskLines.AddRange([string[]]@("[$taskSection]","AddReg=$taskSection.Reg","[$taskSection.Reg]",'HKR,,CLSID,,%Proxy%',('HKR,,FriendlyName,,"{0}"' -f $taskName)))
            if ($taskKind -eq 'Topology') {
                $taskLines.AddRange([string[]]@('HKR,EP\0,%Association%,,%AnyNode%','HKR,EP\0,%EventDriven%,0x00010001,1',('HKR,EP\0,%EndpointName%,,"{0}"' -f $taskName),('HKR,EP\0,%FormFactor%,0x00010001,{0}' -f $taskFactor),('HKR,EP\0,%OemFormat%,0x00000001,'+$taskFormat)))
            }
        }
    }
}
$taskFooter = @'
[Strings]
Provider="OpenAoIP"
Device="OpenAoIP Windows Audio (Development)"
Disk="OpenAoIP Windows Audio Package"
Audio="{6994ad04-93ef-11d0-a3cc-00a0c9223196}"
Render="{65e8773e-8f56-11d0-a3b9-00a0c9223196}"
Capture="{65e8773d-8f56-11d0-a3b9-00a0c9223196}"
Topology="{dda54a40-1e4c-11d1-a050-405705c10000}"
Realtime="{eb115ffc-10c8-4964-831d-6dcb02e6f23f}"
Proxy="{17cca71b-ecd7-11d0-b908-00a0c9223196}"
AnyNode="{00000000-0000-0000-0000-000000000000}"
Association="{1da5d803-d492-4edd-8c23-e0c0ffee7f0e},2"
EventDriven="{1da5d803-d492-4edd-8c23-e0c0ffee7f0e},7"
EndpointName="{a45c254e-df1c-4efd-8020-67d146a850e0},14"
FormFactor="{1da5d803-d492-4edd-8c23-e0c0ffee7f0e},0"
OemFormat="{e4870e26-3cc5-4cd2-ba46-ca0a9a70ed04},3"
'@
$taskLines.AddRange([string[]]($taskFooter -split '\r?\n'))
[IO.File]::WriteAllLines([IO.Path]::GetFullPath($Output),$taskLines,[Text.Encoding]::ASCII)
